uint8_t parity128(uint64_t hi, uint64_t lo){
  uint64_t x = hi ^ lo;
  x ^= x >> 32;
  x ^= x >> 16;
  x ^= x >> 8;
  x ^= x >> 4;
  x ^= x >> 2;
  x ^= x >> 1;
  return (uint8_t)(x & 1);
}
```

